function goEntry(entry, replace = false) { if (isPublicDemo) return openPublicDashboard(); window.history[replace ? 'replaceState' : 'pushState']({}, '', `/login?entry=${encodeURIComponent(entry)}`); beginViewMotion('public'); render(); }
