function notificationPopover() {
  if (!state.notificationsOpen) return '';
  const notifications = state.data?.notifications || [];
  const browserButton = 'Notification' in window && Notification.permission !== 'granted' ? `<button type="button" class="text-button" id="enable-browser-notifications">브라우저 알림 켜기</button>` : '';
  return `<aside class="notification-popover" role="dialog" aria-label="알림"><header><div><b>알림</b><small>최근 ${notifications.length}건</small></div><button class="notification-popover-close" id="close-notifications" aria-label="알림 닫기">×</button></header>${browserButton}<div class="notification-list">${notifications.map((item) => `<button type="button" class="notification-row ${item.readAt ? '' : 'unread'}" data-open-notification="${item.id}" data-proposal="${esc(item.proposalId || '')}"><b>${esc(item.title)}</b><span>${esc(item.body)}</span><small>${fmt(item.createdAt)}${item.readAt ? ' · 읽음' : ' · 새 알림'}</small></button>`).join('') || '<p class="empty">받은 알림이 없습니다.</p>'}</div></aside>`;
}

function proposalStatusClass(status) {
  return ({ draft: 'draft', internal_review: 'review', consulting: 'consulting', approved: 'approved', submitted: 'submitted', closed: 'closed' })[status] || 'draft';
}

function recordFileFor(sourceType, sourceId) {
  return (state.data?.recordFiles || []).find((file) => file.source?.type === sourceType && file.source?.id === sourceId);
}

function recordExportControls(sourceType, sourceId) {
  const file = recordFileFor(sourceType, sourceId);
  if (!file) return '';
  const label = `${file.title} 내보내기`;
  return `<div class="record-export-actions" aria-label="${esc(label)}"><button class="secondary record-file-docx" data-record-file="${file.id}">DOCX</button><button class="secondary record-file-print" data-record-file="${file.id}">PDF로 저장</button></div>`;
}

