  const assignments = (member) => member.orgAssignments?.length ? member.orgAssignments : (member.orgNodeId ? [{ nodeId: member.orgNodeId, position: labels[member.role] || '일반위원' }] : []);
  const nodeName = (nodeId) => nodes.find((node) => node.id === nodeId)?.name || '소속 미정'; const root = nodes.find((node) => !node.parentId); const selectedNode = nodes.find((node) => node.id === state.selectedOrgNodeId) || nodes.find((node) => node.parentId) || root;
