function modal(title, body, onSubmit = null, submitLabel = '저장') { const element = document.createElement('div'); element.className = 'modal-backdrop'; element.innerHTML = `<div class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><button class="modal-close" aria-label="닫기">×</button><h2>${title}</h2><form id="modal-form" class="form-stack">${body}${onSubmit ? `<button class="primary">${esc(submitLabel)}</button>` : ''}</form></div>`; document.body.append(element); const close = () => { if (element.dataset.closing) return; element.dataset.closing = 'true'; element.classList.add('is-leaving'); window.setTimeout(() => element.remove(), 160); }; element.closeModal = close; element.querySelector('.modal-close').onclick = close; element.onclick = (event) => { if (event.target === element) close(); }; if (onSubmit) element.querySelector('#modal-form').onsubmit = async (event) => { event.preventDefault(); try { await onSubmit(Object.fromEntries(new FormData(event.currentTarget)), event.currentTarget); close(); } catch (error) { state.error = error.message; close(); render(); } }; return element; }

function showDeadlineReminder() {
  if (state.deadlineReminderShown || !state.data) return;
  const items = deadlineItems();
  if (!items.length) return;
  state.deadlineReminderShown = true;
  const now = new Date();
  const rows = items.slice(0, 5).map((item) => {
    const overdue = new Date(`${item.dueAt}T23:59:59`) < now;
    return `<button type="button" class="deadline-reminder-row" data-tab="${item.tab}" ${item.meetingId ? `data-meeting="${item.meetingId}"` : ''} ${item.proposalId ? `data-proposal="${item.proposalId}"` : ''}><span class="tag ${overdue ? 'deadline-overdue' : ''}">${overdue ? '기한 지남' : '마감 예정'}</span><div><b>${esc(item.title)}</b><small>${esc(item.detail)} · ${fmt(item.dueAt)}까지</small></div></button>`;
  }).join('');
  const reminder = modal('마감 기한 알림', `<p class="deadline-reminder-copy">내가 맡은 과제와 배정된 검토 중 기한이 있는 항목입니다.</p><div class="deadline-reminder-list">${rows}</div>${items.length > 5 ? `<small>외 ${items.length - 5}건은 내 활동에서 확인할 수 있습니다.</small>` : ''}`);
  reminder.querySelectorAll('[data-tab]').forEach((button) => button.addEventListener('click', () => { reminder.closeModal(); state.tab = button.dataset.tab; state.selectedProposalId = button.dataset.proposal || null; state.selectedMeetingId = button.dataset.meeting || null; beginViewMotion(); render(); }));
}

function openNotifications() { state.notificationsOpen = !state.notificationsOpen; render(); }

function decoratePageTitle() {
  const title = document.querySelector('.topbar h1'); if (!title || title.querySelector('.page-title-icon')) return;
  const label = title.textContent.trim(); const icon = navIcons[state.tab] || '•';
  title.innerHTML = `<span class="page-title-icon" aria-hidden="true">${icon}</span><span>${esc(label)}</span>`;
}

